            not math.isfinite(bin_weight)
            or not math.isfinite(pos_weight)
            or not math.isfinite(prob_weight)
        ):
            raise FloatingPointError(
                "non-finite value encountered during calibration "
                "computation"
            )
        if bin_weight == 0.0:
            continue
